Route::middleware('guest')->group(function () {
    $loginRoles = array_column(RoleName::cases(), 'value');
    Route::get('/login/{role?}', [AuthController::class, 'create'])->whereIn('role', $loginRoles)->name('login');
    Route::post('/login/{role?}', [AuthController::class, 'store'])->whereIn('role', $loginRoles)->name('login.store');
    Route::get('/forgot-password', [PasswordRecoveryController::class, 'create'])->name('password.request');
    Route::post('/forgot-password', [PasswordRecoveryController::class, 'store'])->middleware('throttle:recovery')->name('password.email');
    Route::get('/reset-password/{token}', [PasswordRecoveryController::class, 'edit'])->name('password.reset');
    Route::post('/reset-password', [PasswordRecoveryController::class, 'update'])->middleware('throttle:recovery')->name('password.update');
});
